  if(creationReview&&user)content+=`<section class="panel" role="region" aria-labelledby="private-task-create-title"><h2 id="private-task-create-title">${taskDraft?.event?(taskDraft.editToken?'Save these event changes?':'Create this workspace event?'):taskDraft?.editToken?'Save these task changes?':taskDraft?.schedule?'Create this routine?':taskDraft?.homeGrocery?'Create this grocery item?':'Create this private task?'}</h2><h3>${e(creationReview.title)}</h3><p>${e(creationReview.day||'No due date')}${taskDraft?.event?' · '+e(eventViewSchedule(creationReview,true)):' · '+e(creationReview.section)}</p>${allowTaskPriority&&!taskDraft?.event?`<p>Priority: <strong>${e(creationReview.priority)}</strong></p>`:''}${creationReview.schedule?`<p>Repeat ${e(creationReview.schedule.frequency)} · Interval ${e(creationReview.schedule.interval)} · Starts ${e(creationReview.schedule.anchorDay)}</p>`:''}${allowHomeCleaning&&!taskDraft?.event&&creationReview.homeCleaning?`<p>Room: ${e(creationReview.homeCleaning.room||'Not set')} · Assigned to: ${e(creationReview.homeCleaning.assignee||'Unassigned')} · ${creationReview.homeCleaning.rollover?'Carries forward to later daily lists':'Does not carry forward'}</p>`:''}${allowHomeCleaning&&!taskDraft?.event&&creationReview.homeCleaning===null?'<p>Home cleaning details will be removed.</p>':''}${allowHomeGroceries&&!taskDraft?.event&&creationReview.homeGrocery?`<p>Quantity: ${e(creationReview.homeGrocery.quantity||'Not set')} · ${creationReview.homeGrocery.favorite?'Saved as a favorite':'Not a favorite'}</p>`:''}${allowHomeGroceries&&!taskDraft?.event&&creationReview.homeGrocery===null?'<p>Grocery details will be removed.</p>':''}${allowHomeDeliveries&&!taskDraft?.event&&creationReview.homeDelivery?`<p>Delivery: ${e(creationReview.homeDelivery.status.replaceAll('_',' '))} · Expected: ${e(creationReview.homeDelivery.expectedDay||'Not set')} · Carrier: ${e(creationReview.homeDelivery.carrier||'Not set')}</p><p>Tracking reference: ${e(creationReview.homeDelivery.trackingReference||'Not set')}</p>${creationReview.homeDelivery.refundNote?`<p>Return/refund note: ${e(creationReview.homeDelivery.refundNote)}</p>`:''}`:''}${allowHomeDeliveries&&!taskDraft?.event&&creationReview.homeDelivery===null?'<p>Delivery tracking will be removed.</p>':''}${!taskDraft?.event&&(taskDraft?.editToken?allowTaskDescriptionEdit:allowTaskDescriptions)?`<h3>Description</h3><pre class="private-note-body" tabindex="0" aria-label="Reviewed task description">${'\n'+e(creationReview.description||'No description')}</pre>`:''}${allowTaskSubtasks&&!taskDraft?.event&&!taskDraft?.editToken?`<h3>Checklist steps</h3>${creationReview.subtasks?.length?`<ol>${creationReview.subtasks.map(item=>`<li>${e(item.title)} · Open</li>`).join('')}</ol>`:'<p>No checklist steps</p>'}`:''}${allowTaskChecklistEdit&&taskDraft?.editToken&&!taskDraft?.event&&creationReview.subtasks?`<h3>${allowTaskChecklistTitles?'Checklist after saving':'Checklist completion after saving'}</h3><ul>${creationReview.subtasks.map(item=>`<li>${e(item.title)} · ${item.done?'Completed':'Open'}</li>`).join('')}</ul>`:''}${allowTaskChecklistStructure&&taskDraft?.editToken&&!taskDraft?.event&&creationReview.removedSubtasks?`<p>${creationReview.addedSubtaskCount} new step(s) will start open.</p>${creationReview.removedSubtasks.length?`<h3>Steps to remove</h3><ul class="warning">${creationReview.removedSubtasks.map(item=>`<li>${e(item.title)} · ${item.done?'Completed':'Open'}</li>`).join('')}</ul>`:'<p>No steps will be removed.</p>'}`:''}${taskDraft?.event&&allowCalendarWorkspace?`<h3>Calendar category</h3><p>${e(creationReview.calendarCategory||'Uncategorized')}</p>`:''}${taskDraft?.event&&allowEventDetails?`<h3>Location</h3><p>${e(creationReview.location||'No location')}</p><h3>Event details</h3><pre class="private-note-body" tabindex="0" aria-label="Reviewed event details">${'\n'+e(creationReview.description||'No details')}</pre>`:''}<p>${taskDraft?.event?(taskDraft.editToken?(allowEventDetails?'The reviewed title, date, times, location and details change after approval. Other saved fields stay intact.':'Only this workspace event’s title, date, start time and optional end time change after approval. Other details stay intact.'):'This adds one private workspace event after approval. Connected calendars stay unchanged.'):taskDraft?.editToken?(allowTaskChecklistEdit?'This saves the reviewed task fields and checklist changes after approval. The task’s own completion status and other details stay intact.':allowTaskPriority?'This saves the reviewed task fields, including priority, after approval. Completion and subtasks stay intact.':allowTaskDescriptionEdit?'This changes the task title, date, section and description after approval. Completion and subtasks stay intact.':'This changes only the task title, date and section after approval. Completion and subtasks stay intact.'):'This adds one task after you approve.'}</p><button class="btn btn-primary" type="button" id="private-task-create-approve" ${busy?'disabled':''}>${taskDraft?.event?(taskDraft.editToken?'Approve event changes':'Approve event creation'):taskDraft?.editToken?'Approve task changes':'Approve task creation'}</button></section>`;
